input.sparql:
SELECT DISTINCT ?point ?eq WHERE {
  ?point a brick:Power .
  ?point brick:hasParentAsset ?eq .
}

SELECT DISTINCT ?point ?pointURI ?eq ?eqName ?tsid WHERE {
  ?point a brick:Electric_Power_Sensor .
  OPTIONAL { ?point rdfs:label ?eqName0 . }
  ?point brick:hasParentAsset ?eq .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid . }
}

SELECT DISTINCT ?point ?eq WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point brick:hasParentAsset ?eq .
}

SELECT DISTINCT ?p ?pcls ?o ?ocls WHERE {
  ?p a brick:Electric_Power_Sensor .
  ?p ?rel ?o .
} LIMIT 50

SELECT DISTINCT ?s ?p ?o WHERE {
  ?s a brick:Electric_Power_Sensor .
} LIMIT 20

SELECT DISTINCT ?point ?eqName ?tsid WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
  ?point brick:hasSubProperty|brick:hasParent * ?x .
} LIMIT 5

SELECT DISTINCT ?point ?tsid WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
}

SELECT DISTINCT ?point ?eq ?eqcls ?eqName WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point ?rel ?eq .
  FILTER (!isIRI(?eq) || FILTER(?eq != ?point ))
  ?eq a ?eqcls .
  OPTIONAL { ?point rdfs:label ?pointlbl . }
}

